    /** @var array */
    private array $issues;

    public function __construct(array $issues)
    {
        $this->issues = $issues;
    }

    /**
     * Create from SSResponse object or raw OperationOutcome array.
     */
    public static function fromResponse(SSResponse|array $response): self
    {
        $body = $response instanceof SSResponse ? $response->getBody() : $response;
        $issues = [];

        if (isset($body['issue']) && is_array($body['issue'])) {
            $issues = $body['issue'];
        } elseif (isset($body['resourceType']) && $body['resourceType'] === 'OperationOutcome') {
            $issues = $body['issue'] ?? [];
        } elseif (is_array($body)) {
            $issues = $body;
        }

        return new self($issues);
    }

    /**
     * Extract all rule numbers from issues.
     *
     * @return array<int>
     */
    public function getRuleNumbers(): array
    {
        $numbers = [];
        foreach ($this->issues as $issue) {
            $text = $issue['details']['text'] ?? $issue['details'] ?? '';
            if (preg_match('/RuleNumber:\s*(\d+)/i', (string) $text, $matches)) {
                $numbers[] = (int) $matches[1];
            }
            // Also check expression for rule number pattern
            $expression = $issue['expression'] ?? [];
            foreach ((array) $expression as $expr) {
                if (preg_match('/^(\d+)\s/', (string) $expr, $m)) {
                    $numbers[] = (int) $m[1];
                }
            }
        }

        return array_unique($numbers);
    }

    /**
     * Get info for specific rule number.
     */
    public function getRuleInfo(int $ruleNumber): ?array
    {
        return self::RULE_MAP[$ruleNumber] ?? null;
    }

    /**
     * Get all issues enriched with rule number info.
     *
     * @return array
     */
    public function getParsedIssues(): array
    {
        $parsed = [];

        foreach ($this->issues as $issue) {
            $text = $issue['details']['text'] ?? $issue['details'] ?? '';
            $textStr = (string) $text;
            $expression = $issue['expression'] ?? [];

            // Extract rule number
            $ruleNumber = null;
            if (preg_match('/RuleNumber:\s*(\d+)/i', $textStr, $matches)) {
                $ruleNumber = (int) $matches[1];
            }

            // Get rule info
            $ruleInfo = $ruleNumber !== null ? (self::RULE_MAP[$ruleNumber] ?? null) : null;

            // Detect response type
            $responseType = $this->detectResponseType($textStr, $issue['code'] ?? '');

            $parsed[] = [
                'rule_number' => $ruleNumber,
                'path' => is_array($expression) ? implode(', ', $expression) : (string) $expression,
                'severity' => $issue['severity'] ?? 'error',
                'code' => $issue['code'] ?? '',
                'text' => $textStr,
                'description' => $ruleInfo['description'] ?? ($responseType ? self::RESPONSE_TYPES[$responseType]['title'] ?? '' : ''),
                'terminology' => $ruleInfo['terminology'] ?? '',
                'fix' => $ruleInfo['fix'] ?? ($responseType ? (self::RESPONSE_TYPES[$responseType]['fix'] ?? '') : ''),
                'version' => $ruleInfo['version'] ?? '',
                'last_update' => $ruleInfo['last_update'] ?? '',
                'response_type' => $responseType,
                'raw_issue' => $issue,
            ];
        }

        return $parsed;
    }

    /**
     * Detect response type from error text.
     */
    private function detectResponseType(string $text, string $code): ?string
    {
        $textLower = strtolower($text);

        if (str_contains($textLower, 'duplicate') || $code === 'duplicate') {
            return 'duplicate';
        }
        if (str_contains($textLower, 'code not found')) {
            return 'code_not_found';
        }
        if (str_contains($textLower, 'invalid date time format')) {
            return 'invalid_datetime_format';
        }
        if (str_contains($textLower, 'invalid date time value')) {
            return 'invalid_datetime_value';
        }
        if (str_contains($textLower, 'reference is mandatory') || str_contains($textLower, 'reference must')) {
            return 'reference_mandatory';
        }
        if (str_contains($textLower, 'invalid coding system')) {
            return 'invalid_coding_system';
        }
        if (str_contains($textLower, 'element not found')) {
            return 'element_not_found';
        }
        if (str_contains($textLower, 'invalid identifier system')) {
            return 'invalid_identifier_system';
        }
        if (str_contains($textLower, 'integer formated as a string') || str_contains($textLower, 'integer formatted')) {
            return 'integer_formatted_string';
        }
        if (str_contains($textLower, 'invalid boolean')) {
            return 'invalid_boolean_value';
        }
        if (str_contains($textLower, 'not null') || str_contains($textLower, 'data harus terisi')) {
            return 'not_null';
        }
        if (str_contains($textLower, 'invalid reference') || str_contains($textLower, 'reference to') && str_contains($textLower, 'not valid')) {
            return 'invalid_reference';
        }
        if (str_contains($textLower, 'invalid decimal') || str_contains($textLower, 'invalid type')) {
            return 'invalid_decimal_value';
        }
        if (str_contains($textLower, 'invalid integer')) {
            return 'invalid_integer_value';
        }

        return null;
    }

    /**
     * Human-readable summary of all errors.
     */
    public function getSummary(): string
    {
        $parsed = $this->getParsedIssues();
        $lines = [];

        foreach ($parsed as $issue) {
            $ruleNum = $issue['rule_number'] ?? 'N/A';
            $path = $issue['path'] ?: '-';
            $desc = $issue['description'] ?: $issue['text'] ?: '-';

            $lines[] = "[$ruleNum] $path => $desc";
        }

        return implode(PHP_EOL, $lines);
    }

    /**
     * True if any issue is a duplicate.
     */
    public function isDuplicate(): bool
    {
        foreach ($this->issues as $issue) {
            $text = (string) ($issue['details']['text'] ?? $issue['details'] ?? '');
            if (str_contains(strtolower($text), 'duplicate')) {
                return true;
            }
        }

        return false;
    }

    /**
     * True if any issue is a date/time error.
     */
    public function isDateTimeError(): bool
    {
        foreach ($this->issues as $issue) {
            $text = (string) ($issue['details']['text'] ?? $issue['details'] ?? '');
            if (str_contains(strtolower($text), 'date time') || str_contains(strtolower($text), 'datetime')) {
                return true;
            }
        }

        return false;
    }

    /**
     * Get all affected FHIR paths.
     *
     * @return array<string>
     */
    public function getAffectedPaths(): array
    {
        $paths = [];

        foreach ($this->issues as $issue) {
            $expression = $issue['expression'] ?? [];
            foreach ((array) $expression as $expr) {
                if ($expr) {
                    $paths[] = (string) $expr;
                }
            }
        }

        return array_unique($paths);
    }

    /**
     * Get the raw issues array.
     *
     * @return array
     */
    public function getIssues(): array
    {
        return $this->issues;
    }

    /**
     * Get all available rule numbers in the map.
     *
     * @return array<int>
     */
    public static function getAvailableRuleNumbers(): array
    {
        return array_keys(self::RULE_MAP);
    }

    /**
     * Get all rules for a specific FHIR resource type.
     *
     * @return array<int, array>
     */
    public static function getRulesForResource(string $resourceType): array
    {
        $resourceType .= '.';
        $result = [];

        foreach (self::RULE_MAP as $ruleNumber => $rule) {
            if (str_starts_with($rule['path'], $resourceType)) {
                $result[$ruleNumber] = $rule;
            }
        }

        return $result;
    }

    /**
     * Search rules by keyword in description or terminology.
     *
     * @return array<int, array>
     */
    public static function searchRules(string $keyword): array
    {
        $keyword = strtolower($keyword);
        $result = [];

        foreach (self::RULE_MAP as $ruleNumber => $rule) {
            $desc = strtolower($rule['description']);
            $term = strtolower($rule['terminology']);
            $path = strtolower($rule['path']);

            if (str_contains($desc, $keyword) || str_contains($term, $keyword) || str_contains($path, $keyword)) {
                $result[$ruleNumber] = $rule;
            }
        }

        return $result;
    }

    /**
     * Get the response type info.
     */
    public static function getResponseType(string $type): ?array
    {
        return self::RESPONSE_TYPES[$type] ?? null;
    }
}
